        private void UpdateSplashProgress(int value, string status)
        {
            try
            {
                if (Frm2 != null)
                {
                    if (value >= 0 && value <= 100)
                    {
                        Frm2._progressValue = value;
                    }
                    Frm2._statusText = status ?? "";
                }
            }
            catch { }
        }

