        /// <summary>将 UI/ini 中的触发模式写入相机硬件（不依赖 frm5.mark）。</summary>
        private void ApplyTriggerModeToCameraHardware(int slot)
        {
            if (slot < 0 || slot >= 12 || m_MyCamera[slot] == null) return;
            Myjob job = myjobs[slot];
            // 与打开/关闭/重连互斥，防止半开半关时写触发参数
            lock (_cameraLock)
            {
            try
            {
                bool softChecked = GetSoftTriggerChecked(slot);
                if (job.triggerMode == "连续运行")
                {
                    job.trrigerEn = false;
                    m_MyCamera[slot].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                    SetSoftTriggerEnabled(slot, false);
                    SetTriggerExecEnabled(slot, false);
                }
                else if (job.triggerMode == "触发拍照" || IsCommTriggerMode(job.triggerMode))
                {
                    job.trrigerEn = true;
                    m_MyCamera[slot].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);
                    if (softChecked || IsCommTriggerMode(job.triggerMode))
                    {
                        m_MyCamera[slot].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                        SetTriggerExecEnabled(slot, IsCameraGrabbing(slot));
                    }
                    else
                    {
                        m_MyCamera[slot].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                    }
                    SetSoftTriggerEnabled(slot, true);
                    if (IsCommTriggerMode(job.triggerMode))
                        ClearCommTriggerPending(slot);
                }
            }
            catch (Exception ex)
            {
                MsgErroeLog.WriteLog(ex.Message + "触发切换" + (slot + 1));
            }
            }
        }

        private void ApplyTriggerModesForOpenedCameras()
        {
            if (manager1 == null) return;
            int max = Math.Min(12, manager1.JobCount);
            for (int i = 0; i < max; i++)
            {
                if (m_MyCamera[i] != null)
                    ApplyTriggerModeToCameraHardware(i);
            }
        }

        private void ClearCameraSlotOnOpenFailed(string nnn, ref int t1, ref int t2, ref int t3, ref int t4, ref int t5, ref int t6, ref int t7, ref int t8, ref int t9, ref int t10, ref int t11, ref int t12)
        {
            int slot = int.Parse(nnn);
            if (m_MyCamera[slot] != null)
            {
                try { m_MyCamera[slot].MV_CC_StopGrabbing_NET(); } catch { }
                SetCameraGrabbing(slot, false);
                try { m_MyCamera[slot].MV_CC_CloseDevice_NET(); } catch { }
                try { m_MyCamera[slot].MV_CC_DestroyDevice_NET(); } catch { }
                m_MyCamera[slot] = null;
            }
            ClearCommTriggerPending(slot);
            switch (nnn)
            {
                case "0": t1 = 0; break;
                case "1": t2 = 0; break;
                case "2": t3 = 0; break;
                case "3": t4 = 0; break;
                case "4": t5 = 0; break;
                case "5": t6 = 0; break;
                case "6": t7 = 0; break;
                case "7": t8 = 0; break;
                case "8": t9 = 0; break;
                case "9": t10 = 0; break;
                case "10": t11 = 0; break;
                case "11": t12 = 0; break;
            }
        }

        private void ApplyGigePacketSizeAfterOpen(int slot, int deviceArrayIndex)
        {
            try
            {
                if (slot < 0 || slot >= 12 || m_MyCamera[slot] == null) return;
                if (deviceArrayIndex < 0 || deviceArrayIndex >= device1.Length) return;
                if (device1[deviceArrayIndex].nTLayerType != MyCamera.MV_GIGE_DEVICE) return;
                int nPacketSize = m_MyCamera[slot].MV_CC_GetOptimalPacketSize_NET();
                if (nPacketSize > 0)
                    m_MyCamera[slot].MV_CC_SetIntValue_NET("GevSCPSPacketSize", (uint)nPacketSize);
            }
            catch { }
        }

        private bool ReconnectCameraSlot(int slot, int deviceArrayIndex, out int nRet)
        {
            nRet = -1;
            if (slot < 0 || slot >= 12 || deviceArrayIndex < 0 || deviceArrayIndex >= device1.Length) return false;
            lock (_cameraLock)
            {
                if (m_MyCamera[slot] == null)
                    m_MyCamera[slot] = new MyCamera();
                try { m_MyCamera[slot].MV_CC_StopGrabbing_NET(); } catch { }
                SetCameraGrabbing(slot, false);
                try { m_MyCamera[slot].MV_CC_CloseDevice_NET(); } catch { }
                try { m_MyCamera[slot].MV_CC_DestroyDevice_NET(); } catch { }
                nRet = m_MyCamera[slot].MV_CC_CreateDevice_NET(ref device1[deviceArrayIndex]);
                if (nRet != MyCamera.MV_OK) return false;
                nRet = m_MyCamera[slot].MV_CC_OpenDevice_NET();
                if (nRet != MyCamera.MV_OK)
                {
                    // 打开失败时销毁已创建的设备句柄，防止句柄泄漏
                    try { m_MyCamera[slot].MV_CC_DestroyDevice_NET(); } catch { }
                    return false;
                }
                ApplyGigePacketSizeAfterOpen(slot, deviceArrayIndex);
                nRet = m_MyCamera[slot].MV_CC_RegisterImageCallBackEx_NET(cbImage, (IntPtr)slot);
                return nRet == MyCamera.MV_OK;
            }
        }

        private bool PrepareCameraGrab(int camIndex, out int nRet)
        {
            nRet = -1;
            if (camIndex < 0 || camIndex >= 12 || m_MyCamera[camIndex] == null)
            {
                MsgErroeLog.WriteLog("相机" + (camIndex + 1) + "未连接，无法启动取流");
                return false;
            }
            lock (_cameraLock)
            {
            try
            {
                if (!m_MyCamera[camIndex].MV_CC_IsDeviceConnected_NET())
                {
                    MsgErroeLog.WriteLog("相机" + (camIndex + 1) + "设备未连接(IsDeviceConnected=false)");
                    return false;
                }
            }
            catch
            {
                MsgErroeLog.WriteLog("相机" + (camIndex + 1) + "连接状态检查失败");
                return false;
            }
            if (IsCameraGrabbing(camIndex))
            {
                m_MyCamera[camIndex].MV_CC_StopGrabbing_NET();
                SetCameraGrabbing(camIndex, false);
                Thread.Sleep(50);
            }
            MyCamera.MVCC_INTVALUE stParam = new MyCamera.MVCC_INTVALUE();
            nRet = m_MyCamera[camIndex].MV_CC_GetIntValue_NET("PayloadSize", ref stParam);
            if (MyCamera.MV_OK != nRet)
            {
                MsgErroeLog.WriteLog("相机" + (camIndex + 1) + " Get PayloadSize failed:" + nRet);
                return false;
            }
            if (!EnsureDriverBuffer(camIndex, stParam.nCurValue))
            {
                MsgErroeLog.WriteLog("相机" + (camIndex + 1) + " 缓存分配失败");
                return false;
            }
            m_stFrameInfo[camIndex].nFrameLen = 0;
            m_stFrameInfo[camIndex].enPixelType = MyCamera.MvGvspPixelType.PixelType_Gvsp_Undefined;
            SetCameraGrabbing(camIndex, true);
            nRet = m_MyCamera[camIndex].MV_CC_StartGrabbing_NET();
            if (MyCamera.MV_OK != nRet)
            {
                SetCameraGrabbing(camIndex, false);
                MsgErroeLog.WriteLog("相机" + (camIndex + 1) + " Start Grabbing Fail:" + nRet);
                return false;
            }
            if (IsCommTriggerMode(myjobs[camIndex].triggerMode))
                ClearCommTriggerPending(camIndex);
            return true;
            }
        }
