                        && IsCommTriggerMode(myjob.triggerMode) && !_commTriggerArmed)
                        return;

                    if (myjob.job.State == CogJobStateConstants.Stopped)
                    {

                        if ((!myjob.trrigerEn) && (myjob.trriger == 0) || (myjob.trriger == 0 && myjob.trrigerEn))
