                                                numericUpDown3.Value = jiajutemp;
                                            }));
                                            myjob1.block.Inputs["jiajuhao"].Value = jiajutemp;
                                        }
                                    }
                                }
                                #endregion

                            }
                            catch (Exception ex)
                            {
                                MsgErroeLog.WriteLog(ex.Message + "相机" + myjob.path_number + "取图");
                            };

                        }

                        if (myjob.trriger == 1 || (camIdx >= 0 && camIdx < 12 && bmp[camIdx] != null))
                        {
                            jobnumber = myjob.numberng;

                            cuowu1 = "";
                            if (myjob.trriger == 1)
                            {
                                try
                                {
                                    AssignBlockInputImage(myjob.block, myjob.img, myjob.Color);
