                            }
                            if (_switchingScheme)
                            {
                                ReleaseFrameBitmap(camIdx);
                                return;   // 方案切换中：丢弃旧帧，停止检测
                            }
                            // 检测中计数（供方案切换排空等待，替代固定 Sleep）
                            Interlocked.Increment(ref _detectingCount);
                            bool runOk = false;
                            try
                            {
                                myjob.block.Run();
                                runOk = true;
                            }
                            catch (Exception exRun)
