        /// <summary>
        /// 界面监控：35ms 周期刷新各相机状态/丢帧数/统计显示
        /// </summary>
        private void UI_monitor()
        {
            while (!_disposingFlag)
            {
                Thread.Sleep(35);
                if (_disposingFlag) break;
                if (zhuanhuan == 0)
                {
                    zhuanhuan = 1;
