        /// <summary>
        /// 相机1 OK 线输出（由 outputok 属性赋值触发，异步线程执行）
        /// </summary>
        public void IO1OK()
        {
            try
            {
                if (myjob1.outputok == 0)
                {
                    output_camera(1, false);
                    this.Invoke(new Action(() => {
                        button55.BackColor = Color.Red;
                    }));

                }
                else if (myjob1.outputok >= 1)
                {
                    if (myjob1.outputok2 == 1)
                    {
                        if (myjob1.IOyanshi != 0)
                            Thread.Sleep(myjob1.IOyanshi);
                        // 延时期间可能有更新的复位/更新请求，重新校验后再置位，防止过期请求误输出（输出卡死）
                        if (myjob1.outputok >= 1 && myjob1.outputok2 == 1)
                        {
                            output_camera(1, true);
                            this.Invoke(new Action(() => {
                                button55.BackColor = Color.Green;
                            }));
                        }

                    }
                }

            }
            catch (Exception ex)
            {
                MsgErroeLog.WriteLog("IO1OK异常: " + ex.Message);
            }
        }
