        private void output_camera(uint a, Boolean b)
        {
            // ★ 关键修复：检查是否正在释放或相机对象是否为空
            if (_disposingFlag || m_MyCamera[0] == null) return;

            lock (locker1)
            {
                if (dahua)
                    a = a - 1;
                try
                {
                    int nRet;
                    nRet = m_MyCamera[0].MV_CC_SetEnumValue_NET("LineSelector", a);
                    if (MyCamera.MV_OK != nRet)
                    {
                        MsgErroeLog.WriteLog("Set Fail1!" + nRet);
                        return;
                    }
                    nRet = m_MyCamera[0].MV_CC_SetBoolValue_NET("LineInverter", b);
                    if (MyCamera.MV_OK != nRet)
                    {
                        MsgErroeLog.WriteLog("Set Fail2!" + nRet);
                        return;
                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog("IOO1~~~~~~~~~" + b + ex.Message);
                }

            }
        }
        private void output_camera1ng(uint a, Boolean b)
        {
            if (_disposingFlag || m_MyCamera[0] == null) return;

            lock (locker1)
            {
                if (dahua)
                    a = a - 1;
                try
                {
                    int nRet;
                    nRet = m_MyCamera[0].MV_CC_SetEnumValue_NET("LineSelector", a);
                    if (nRet != MyCamera.MV_OK) { MsgErroeLog.WriteLog("IO输出1-NG: LineSelector失败 ret=0x" + Convert.ToString(nRet, 16)); return; }
                    nRet = m_MyCamera[0].MV_CC_SetBoolValue_NET("LineInverter", b);
                    if (nRet != MyCamera.MV_OK) { MsgErroeLog.WriteLog("IO输出1-NG: LineInverter失败 ret=0x" + Convert.ToString(nRet, 16)); }
                }
                catch (Exception ex) { MsgErroeLog.WriteLog("IO输出1-NG异常: " + ex.Message); }
            }
        }
        private void output_camera2(uint a, Boolean b)
        {
            if (_disposingFlag || m_MyCamera[1] == null) return;
            if (manager1 == null || manager1.JobCount <= 1) return;

            lock (locker2)
            {
                if (dahua)
                    a = a - 1;
                try
                {
                    int nRet;
                    nRet = m_MyCamera[1].MV_CC_SetEnumValue_NET("LineSelector", a);
                    if (nRet != MyCamera.MV_OK)
                    {
                        MsgErroeLog.WriteLog("IO输出2: LineSelector失败 ret=0x" + Convert.ToString(nRet, 16) + " line=" + a);
                        return;
                    }
                    nRet = m_MyCamera[1].MV_CC_SetBoolValue_NET("LineInverter", b);
                    if (nRet != MyCamera.MV_OK)
                    {
                        MsgErroeLog.WriteLog("IO输出2: LineInverter失败 ret=0x" + Convert.ToString(nRet, 16) + " val=" + b);
                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog("IO输出2异常: " + ex.Message);
                }
            }
        }
