        private void comboBox1_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (frm5.mark == 1 || myjob1.state.Contains("相"))
            {
                try
                {
                    if (comboBox1.Text == "连续运行")
                    {
                        m_MyCamera[0].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                        cbSoftTrigger1.Enabled = false;
                        bnTriggerExec1.Enabled = false;
                    }
                    else if (comboBox1.Text == "触发拍照" || comboBox1.Text == "通讯触发")
                    {

                        m_MyCamera[0].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);

                        // ch:触发源选择:0 - Line0; | en:Trigger source select:0 - Line0;
                        //           1 - Line1;
                        //           2 - Line2;
                        //           3 - Line3;
                        //           4 - Counter;
                        //           7 - Software;
                        if (cbSoftTrigger1.Checked || comboBox1.Text == "通讯触发")
                        {
                            m_MyCamera[0].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                            if (m_bGrabbing1)
                            {
                                bnTriggerExec1.Enabled = true;
                            }
                        }
                        else
                        {
                            m_MyCamera[0].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                        }
                        cbSoftTrigger1.Enabled = true;

                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog(ex.Message + "触发切换1");
                }
                myjob1.triggerMode = comboBox1.Text;
            }
        }
