        /// <summary>
        /// 检查触发条件是否满足
        /// </summary>
        /// <param name="receivedValue">接收到的数据值</param>
        /// <param name="triggerChar">配置的触发字符</param>
        /// <param name="mode">触发模式: 相等/包含/范围</param>
        /// <param name="val1">触发值（相等/包含时用；范围时为最小值）</param>
        /// <param name="val2">范围模式时的最大值</param>
        /// <returns>是否满足触发条件</returns>
        private bool CheckTriggerCondition(string receivedValue, string mode, string val1, string val2)
        {
            return CommTriggerHelper.CheckTriggerCondition(receivedValue, mode, val1, val2);
        }

        /// <summary>
        /// 仅在触发条件成立时写入流程输入并软触发拍照
        /// </summary>
        private void ApplyCommTrigger(Myjob job, int cameraIndex, string selection, string mode, string val1, string val2, string inputKey)
        {
            if (!CheckTriggerCondition(selection, mode, val1, val2)) return;
            if (manager1 == null || cameraIndex < 0 || cameraIndex >= 12) return;
            if (manager1.JobCount <= cameraIndex) return;
            if (job == null || job.en != 1) return;
            if (m_MyCamera[cameraIndex] == null) return;
            if (!_commTriggerArmed) return;
            try
            {
                if (job.block != null && job.block.Inputs.Contains(inputKey))
                    job.block.Inputs[inputKey].Value = selection;
            }
            catch { }
            job.jieshouZifu = selection;
            int nRet = TriggerSoftwareCamera(cameraIndex);
            if (MyCamera.MV_OK != nRet)
                MsgErroeLog.WriteLog("Trigger Software Fail!---" + nRet);
        }

        private static void GetCamTrigParams(string[] camRow, out string mode, out string val1, out string val2)
        {
            CommTriggerHelper.GetCamTrigParams(camRow, out mode, out val1, out val2);
        }

        /// <summary>
        /// OMRON Fins 通讯触发：收到切型指令后异步执行方案切换
        /// </summary>
        private void DataChange_fins(object sender, FormOmron.SelectionChangedEventArgs e)
        {
            if (yunxing)
            {
                for (int i = 0; i < 12; i++)
                {
                    if (e.Camera != (i + 1).ToString()) continue;
                    if (!omron.camera_dic.ContainsKey(i + 1)) continue;
                    GetCamTrigParams(omron.camera_dic[i + 1], out string mode, out string tv1, out string tv2);
                    ApplyCommTrigger(myjobs[i], i, e.Selection, mode, tv1, tv2, "fins");
                }
            }
            if (e.Camera.Contains("13"))
            {
                if (path_1 != omron.lujing.Replace("\0", "") && qiehuanzhong == 0)
                {
                    if (omron.camera_dic[13][2] == "true")
                    {
                        if (!omron.camera_dic[13][1].Contains("无"))
                        {
                            omron.camera_dic[13][4] = omron.camera_dic[13][1];
                            omron.camera_dic[13][5] = omron.camera_dic[13][0];

                            omron.fins_xie[12] = true;
                        }

                        Task.Run(() =>
                        {
                            try
                            {
                                // 方案切换涉及大量 UI 操作，收口到 UI 线程执行（原在后台线程直接操作控件）
                                if (InvokeRequired)
                                    Invoke(new Action(() => xinghao_qiehuan(omron.lujing.Replace("\0", ""))));
                                else
                                    xinghao_qiehuan(omron.lujing.Replace("\0", ""));
                            }
                            finally
                            {
                                // 无论成功失败都复位，防止该通道切换被永久锁死
                                omron.qiehuanzhong = 0;
                            }
                        });
                    }
                }
                else
                {
                    if (!omron.camera_dic[13][1].Contains("无"))
                    {
                        omron.camera_dic[13][4] = omron.camera_dic[13][1];
                        omron.camera_dic[13][5] = omron.camera_dic[13][0];
                        omron.fins_xie[12] = true;
                    }
                    omron.qiehuanzhong = 0;
                }
            }
            this.Invoke(new Action(() =>
            {
                textBox1.Text = e.Selection;
            }));
        }
