        {
            if (yunxing)
            {
                for (int i = 0; i < 12; i++)
                {
                    if (e.Camera != (i + 1).ToString()) continue;
                    if (!modbustcp.camera_dic.ContainsKey(i + 1)) continue;
                    GetCamTrigParams(modbustcp.camera_dic[i + 1], out string mode, out string tv1, out string tv2);
                    ApplyCommTrigger(myjobs[i], i, e.Selection, mode, tv1, tv2, "modbustcp");
                }
            }
            if (e.Camera.Contains("13"))
            {
                if (path_1 != modbustcp.lujing.Replace("\0", "") && qiehuanzhong == 0)
                {
                    if (modbustcp.camera_dic[13][2] == "true")
                    {
                        if (!modbustcp.camera_dic[13][1].Contains("无"))
                        {
                            modbustcp.camera_dic[13][4] = modbustcp.camera_dic[13][1];
                            modbustcp.camera_dic[13][5] = modbustcp.camera_dic[13][0];

                            modbustcp.fins_xie[12] = true;
                        }

                        Task.Run(() =>
                        {
                            try
                            {
                                // 方案切换涉及大量 UI 操作，收口到 UI 线程执行（原在后台线程直接操作控件）
                                if (InvokeRequired)
                                    Invoke(new Action(() => xinghao_qiehuan(modbustcp.lujing.Replace("\0", ""))));
                                else
                                    xinghao_qiehuan(modbustcp.lujing.Replace("\0", ""));
                            }
                            finally
                            {
                                // 无论成功失败都复位，防止该通道切换被永久锁死
                                modbustcp.qiehuanzhong = 0;
                            }
                        });
                    }
                }
                else
                {
                    if (!modbustcp.camera_dic[13][1].Contains("无"))
                    {
                        modbustcp.camera_dic[13][4] = modbustcp.camera_dic[13][1];
                        modbustcp.camera_dic[13][5] = modbustcp.camera_dic[13][0];
                        modbustcp.fins_xie[12] = true;
                    }
                    modbustcp.qiehuanzhong = 0;
                }
            }
            this.Invoke(new Action(() =>
            {
                textBox1.Text = e.Selection;
            }));
        }
