                                    {
                                        myjob1.index = i_temp;
                                        nnn = "0";
                                        temp1 = 1;
                                    }
                                    if (gigeInfo.chUserDefinedName == camera_name[1])
                                    {
                                        myjob2.index = i_temp;
                                        nnn = "1";
                                        temp2 = 2;
                                    }
                                    if (gigeInfo.chUserDefinedName == camera_name[2])
                                    {
