            //if (m_bGrabbing1 == true)
            //{
            //    m_bGrabbing1 = false;
            //    m_hReceiveThread.Join();
            //}
            //}
            //catch { }


            try
            {

                bnOpen.Enabled = true;
                bnClose.Enabled = false;
                bnTriggerExec1.Enabled = false;
                bnStartGrab1.Enabled = false;
                bnStopGrab1.Enabled = false;
