        {
            trriger2_temp = 0;
            timer8.Enabled = false;
        }

        private void comboBox4_SelectedIndexChanged_1(object sender, EventArgs e)
        {
            if (frm5.mark == 1 || myjob2.state.Contains("相"))
            {
                try
                {
                    if (comboBox4.Text == "连续运行")
                    {
                        m_MyCamera[1].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                        cbSoftTrigger2.Enabled = false;
                        bnTriggerExec2.Enabled = false;
                    }
                    else if (comboBox4.Text == "触发拍照" || comboBox4.Text == "通讯触发")
                    {

                        m_MyCamera[1].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);

                        // ch:触发源选择:0 - Line0; | en:Trigger source select:0 - Line0;
                        //           1 - Line1;
                        //           2 - Line2;
                        //           3 - Line3;
                        //           4 - Counter;
                        //           7 - Software;
                        if (cbSoftTrigger2.Checked || comboBox4.Text == "通讯触发")
                        {
                            m_MyCamera[1].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                            if (m_bGrabbing2)
                            {
                                bnTriggerExec2.Enabled = true;
                            }
                        }
                        else
                        {
                            m_MyCamera[1].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                        }
                        cbSoftTrigger2.Enabled = true;

                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog(ex.Message + "触发切换2");
                }
                myjob2.triggerMode = comboBox4.Text;
            }
        }

