        private void timer12_Tick(object sender, EventArgs e)
        {
            if (myjob4.trriger == 0)
            {
                if (trriger4_temp == 1)
                {
                    int count = listBox9.Items.Count;
                    int select = listBox9.SelectedIndex;
                    this.Invoke(new Action(() =>
                    {
                        if (select < count - 1)
                        {
                            listBox9.SelectedIndex = select + 1;
                        }
                        else
                            listBox9.SelectedIndex = 0;
                    }));
                }

            }
        }

