        private void comboBox5_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (frm5.mark == 1 || myjob3.state.Contains("相"))
            {
                try
                {
                    if (comboBox5.Text == "连续运行")
                    {
                        m_MyCamera[2].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                        cbSoftTrigger3.Enabled = false;
                        bnTriggerExec3.Enabled = false;
                    }
                    else if (comboBox5.Text == "触发拍照" || comboBox5.Text == "通讯触发")
                    {

                        m_MyCamera[2].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);

                        // ch:触发源选择:0 - Line0; | en:Trigger source select:0 - Line0;
                        //           1 - Line1;
                        //           2 - Line2;
                        //           3 - Line3;
                        //           4 - Counter;
                        //           7 - Software;
                        if (cbSoftTrigger3.Checked || comboBox5.Text == "通讯触发")
                        {
                            m_MyCamera[2].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                            if (m_bGrabbing3)
                            {
                                bnTriggerExec3.Enabled = true;
                            }
                        }
                        else
                        {
                            m_MyCamera[2].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                        }
                        cbSoftTrigger3.Enabled = true;

                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog(ex.Message + "触发切换3");
                }
                myjob3.triggerMode = comboBox5.Text;
            }
        }

