        private void UpdateTabNavVisibility()
        {
            if (this.InvokeRequired)
            {
                this.Invoke(new Action(UpdateTabNavVisibility));
                return;
            }
            int jobCount = (manager1 != null) ? manager1.JobCount : 0;
            for (int i = 0; i < 12; i++)
            {
                tabNavButtons[i].Visible = (i < jobCount);
            }
        }
        private bool WaitForManagerLoaded()
        {
            MsgErroeLog.WriteLog("等待方案加载... 当前状态=" + managerState);
            int waitCount = 0;
            while (managerState == ManagerState.Loading && waitCount < 100)
            {
                Thread.Sleep(100);
                waitCount++;
            }
            if (managerState == ManagerState.Loaded)
            {
                MsgErroeLog.WriteLog("方案加载成功，等待了" + (waitCount * 100) + "ms，JobCount=" + manager1.JobCount);
                return true;
            }
            else if (managerState == ManagerState.Failed)
            {
                MsgErroeLog.WriteLog("方案已确定加载失败，等待了" + (waitCount * 100) + "ms");
                return false;
            }
            else
            {
                MsgErroeLog.WriteLog("方案加载超时，等待了" + (waitCount * 100) + "ms后仍在加载中");
                return false;
            }
        }
        private void baoguang_set()
        {
            if (!WaitForManagerLoaded())
            {
                MsgErroeLog.WriteLog("baoguang_set: managerState=" + managerState + "，跳过曝光设置");
                return;
            }
            this.Invoke(new Action(() =>
            {
                for (int i = 0; i < 12 && i < manager1.JobCount; i++)
                {
                    string camSection = "camera" + (i + 1);
                    bool fromVpp = false;
                    // ★ 优先从VPP block读取曝光值
                    try
                    {
                        if (myjobs[i].block != null && myjobs[i].block.Inputs.Contains("baoguang"))
                        {
                            myjobs[i].baoguang = float.Parse(myjobs[i].block.Inputs["baoguang"].Value.ToString());
                            tbExposure[i].Text = myjobs[i].baoguang.ToString();
                            fromVpp = true;
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从VPP block读取曝光=" + myjobs[i].baoguang);
                        }
                    }
                    catch (Exception ex)
                    {
                        MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 读取VPP曝光失败: " + ex.Message);
                    }
                    // ★ VPP block无baoguang输入时，从code.ini读取曝光值
                    if (!fromVpp)
                    {
                        try
                        {
                            string iniExp = canshuIni.ReadString(camSection, "exposure", "1000");
                            float expVal = float.Parse(iniExp);
                            myjobs[i].baoguang = expVal;
                            tbExposure[i].Text = expVal.ToString();
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从code.ini读取曝光=" + expVal);
                        }
                        catch (Exception ex)
                        {
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从code.ini读取曝光失败: " + ex.Message);
                        }
                    }
                    // ★ 从VPP block读取增益值（如果block有此输入）
                    bool gainFromVpp = false;
                    try
                    {
                        if (myjobs[i].block != null && myjobs[i].block.Inputs.Contains("zengyi"))
                        {
                            float gainVal = float.Parse(myjobs[i].block.Inputs["zengyi"].Value.ToString());
                            switch (i)
                            {
                                case 0: tbGain1.Text = gainVal.ToString(); break;
                                case 1: tbGain2.Text = gainVal.ToString(); break;
                                case 2: tbGain3.Text = gainVal.ToString(); break;
                                case 3: tbGain4.Text = gainVal.ToString(); break;
                                case 4: tbGain5.Text = gainVal.ToString(); break;
                                case 5: tbGain6.Text = gainVal.ToString(); break;
                                case 6: tbGain7.Text = gainVal.ToString(); break;
                                case 7: tbGain8.Text = gainVal.ToString(); break;
                                case 8: tbGain9.Text = gainVal.ToString(); break;
                                case 9: tbGain10.Text = gainVal.ToString(); break;
                                case 10: tbGain11.Text = gainVal.ToString(); break;
                                case 11: tbGain12.Text = gainVal.ToString(); break;
                            }
                            gainFromVpp = true;
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从VPP block读取增益=" + gainVal);
                        }
                    }
                    catch (Exception ex)
                    {
                        MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 读取VPP增益失败: " + ex.Message);
                    }
                    // ★ VPP block无增益输入时，从code.ini读取增益值
                    if (!gainFromVpp)
                    {
                        try
                        {
                            string iniGain = canshuIni.ReadString(camSection, "gain", "1");
                            float gainVal = float.Parse(iniGain);
                            switch (i)
                            {
                                case 0: tbGain1.Text = gainVal.ToString(); break;
                                case 1: tbGain2.Text = gainVal.ToString(); break;
                                case 2: tbGain3.Text = gainVal.ToString(); break;
                                case 3: tbGain4.Text = gainVal.ToString(); break;
                                case 4: tbGain5.Text = gainVal.ToString(); break;
                                case 5: tbGain6.Text = gainVal.ToString(); break;
                                case 6: tbGain7.Text = gainVal.ToString(); break;
                                case 7: tbGain8.Text = gainVal.ToString(); break;
                                case 8: tbGain9.Text = gainVal.ToString(); break;
                                case 9: tbGain10.Text = gainVal.ToString(); break;
                                case 10: tbGain11.Text = gainVal.ToString(); break;
                                case 11: tbGain12.Text = gainVal.ToString(); break;
                            }
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从code.ini读取增益=" + gainVal);
                        }
                        catch (Exception ex)
                        {
                            MsgErroeLog.WriteLog("baoguang_set: 相机" + (i + 1) + " 从code.ini读取增益失败: " + ex.Message);
                        }
                    }
                    // ★ 从code.ini读取帧率（确保bnSetParam_Click不会因空值而跳过）
                    try
                    {
                        string iniRate = canshuIni.ReadString(camSection, "rate", "500");
                        switch (i)
                        {
                            case 0: tbFrameRate1.Text = iniRate; break;
                            case 1: tbFrameRate2.Text = iniRate; break;
                            case 2: tbFrameRate3.Text = iniRate; break;
                            case 3: tbFrameRate4.Text = iniRate; break;
                            case 4: tbFrameRate5.Text = iniRate; break;
                            case 5: tbFrameRate6.Text = iniRate; break;
                            case 6: tbFrameRate7.Text = iniRate; break;
                            case 7: tbFrameRate8.Text = iniRate; break;
                            case 8: tbFrameRate9.Text = iniRate; break;
                            case 9: tbFrameRate10.Text = iniRate; break;
                            case 10: tbFrameRate11.Text = iniRate; break;
                            case 11: tbFrameRate12.Text = iniRate; break;
                        }
                    }
                    catch { }
                }

                try
                {
                    decimal datatemp = 1;
                    decimal.TryParse(myjob1.block.Inputs["jiajuhao"].Value.ToString(), out datatemp);
                    numericUpDown3.Value = datatemp;
                    zhuanpanEn = true;
                    numericUpDown3.Visible = true;
                    label73.Visible = true;
                }
                catch
                {
                    zhuanpanEn = false;
                    numericUpDown3.Visible = false;
                    label73.Visible = false;
                }
            }));
        }
