        private void comboBox25_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (frm5.mark == 1 || myjob5.state.Contains("相"))
            {
                try
                {
                    if (comboBox25.Text.Contains("连续运行"))
                    {
                        m_MyCamera[4].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                        cbSoftTrigger5.Enabled = false;
                        bnTriggerExec5.Enabled = false;
                    }
                    else if (comboBox25.Text.Contains("触发拍照") || comboBox25.Text.Contains("通讯触发"))
                    {

                        m_MyCamera[4].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);

                        // ch:触发源选择:0 - Line0; | en:Trigger source select:0 - Line0;
                        //           1 - Line1;
                        //           2 - Line2;
                        //           3 - Line3;
                        //           4 - Counter;
                        //           7 - Software;
                        if (cbSoftTrigger5.Checked || comboBox25.Text.Contains("通讯触发"))
                        {
                            m_MyCamera[4].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                            if (m_bGrabbing5)
                            {
                                bnTriggerExec5.Enabled = true;
                            }
                        }
                        else
                        {
                            m_MyCamera[4].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                        }
                        cbSoftTrigger5.Enabled = true;

                    }
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog(ex.Message + "触发切换5");
                }
                myjob5.triggerMode = comboBox25.Text;
            }
        }

