        private void bnStopGrab12_Click(object sender, EventArgs e)
        {
            try
            {
                if (m_bGrabbing12 == true)
                {
                    m_bGrabbing12 = false;
                    int nRet = m_MyCamera[11].MV_CC_StopGrabbing_NET();
                    if (nRet != MyCamera.MV_OK)
                    {
                        ShowErrorMsg("Stop Grabbing Fail!", nRet);
                    }
                }
                bnStartGrab12.Enabled = true;
                bnStopGrab12.Enabled = false;
            }
            catch
            { MsgErroeLog.WriteLog("相机12停止采集"); }
        }

