                        {
                            if (tool is CogToolBlock)
                            {
                                block_temp = tool as CogToolBlock;
                                youwu = 0;
                                for (int i = 0; i < block_temp.Outputs.Count; i++)
                                {
                                    if (block_temp.Outputs[i].Name == "RunStatus")
                                    {
                                        youwu = 1;
                                    }
                                }
                                if (youwu == 1)
                                {
                                    if (block_temp.Outputs["RunStatus"].Value.ToString() == "0")
                                    {
