        private void comboBox42_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (!yunxing && Frm2.start == 1)
            {
                try
                {
                    myjob9.block = (CogToolBlock)CogSerializer.LoadObjectFromFile(wenjianjia + "\\9\\" + comboBox42.SelectedItem.ToString());
                    canshuIni.WriteString("camera9", "fen", comboBox42.SelectedItem.ToString());
                    MessageBox.Show("切换流程9:" + comboBox42.SelectedItem.ToString() + "成功");
                }
                catch (Exception ex)
                {
                    MsgErroeLog.WriteLog(ex.Message);
                    MessageBox.Show("切换流程9:" + comboBox42.SelectedItem.ToString() + "失败");
                }
            }
        }

        private void comboBox43_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (frm5.mark == 1 || myjob9.state.Contains("相"))
            {
                try
                {
                    if (comboBox43.Text == "连续运行")
                    {
                        m_MyCamera[8].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_OFF);
                        cbSoftTrigger9.Enabled = false;
                        bnTriggerExec9.Enabled = false;
                    }
                    else if (comboBox43.Text == "触发拍照" || comboBox43.Text == "通讯触发")
                    {
                        m_MyCamera[8].MV_CC_SetEnumValue_NET("TriggerMode", (uint)MyCamera.MV_CAM_TRIGGER_MODE.MV_TRIGGER_MODE_ON);
                        if (comboBox43.Text == "触发拍照")
                        {
                            m_MyCamera[8].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_LINE0);
                            cbSoftTrigger9.Enabled = false;
                            bnTriggerExec9.Enabled = false;
                        }
                        else
                        {
                            m_MyCamera[8].MV_CC_SetEnumValue_NET("TriggerSource", (uint)MyCamera.MV_CAM_TRIGGER_SOURCE.MV_TRIGGER_SOURCE_SOFTWARE);
                            if (m_bGrabbing9)
                            {
                                cbSoftTrigger9.Enabled = true;
                                bnTriggerExec9.Enabled = true;
                            }
                        }
                    }
                }
                catch { }
                myjob9.triggerMode = comboBox43.Text;
            }
        }

